(function(){
 'use strict';
 const C=Stratum,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],STORE='stratum-training-v3';
 let state=C.defaults(),page='training',active=null,range=null,countdownTimer=null,boardTimer=null,chartSkill='precision';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const skillBy=id=>C.skills.find(s=>s.id===id),date=at=>new Date(at).toLocaleDateString(undefined,{month:'short',day:'numeric'}),inputName=()=>state.settings.device==='trackpad'?'Trackpad':C.inputMode(state.settings)==='touch'?'Touch':'Mouse';
 const paths={training:'M3 12h4m10 0h4M12 3v4m0 10v4M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',progress:'M4 3v17h17M7 15l4-5 4 2 5-7',leaderboard:'M5 20v-7h4v7m2 0V5h4v15m2 0V9h4v11',settings:'M5 3v18m7-18v18m7-18v18M2 8h6m1 8h6m1-10h6'};
 const icon=id=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]}"/></svg>`;
 const btn=(label,action,kind='primary',extra='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;
 function notify(message,error=false){const p=document.createElement('div');p.className='toast'+(error?' error':'');p.textContent=message;$('#toast-region').replaceChildren(p);setTimeout(()=>p.remove(),5000);}
 try{const saved=localStorage.getItem(STORE);if(saved)state=C.validate(JSON.parse(saved));}catch{setTimeout(()=>notify('Saved data could not be read. Export your existing backup before replacing it.',true),200);}
 function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));$('#save-status').textContent='Saved on this device';}catch{$('#save-status').textContent='Unsaved';notify('Storage is full or unavailable. Export your progress in Settings.',true);}}
 function apply(){const s=state.settings;document.documentElement.dataset.theme=s.theme;document.documentElement.classList.toggle('reduced',s.reduced);document.documentElement.style.setProperty('--accent',s.accent);const rgb=s.accent.slice(1).match(/../g).map(x=>parseInt(x,16)/255),lum=rgb.reduce((n,x,i)=>n+(x<=.04045?x/12.92:((x+.055)/1.055)**2.4)*[.2126,.7152,.0722][i],0);document.documentElement.style.setProperty('--accent-ink',lum>.179?'#111315':'#ffffff');let accessible=rgb.map(v=>v*255),background=s.theme==='light'?.912:.009;const luminance=a=>a.reduce((n,v,i)=>{v/=255;return n+(v<=.04045?v/12.92:((v+.055)/1.055)**2.4)*[.2126,.7152,.0722][i];},0);for(let i=0;i<64&&(Math.max(luminance(accessible),background)+.05)/(Math.min(luminance(accessible),background)+.05)<4.5;i++)accessible=accessible.map(v=>s.theme==='light'?Math.max(0,v-4):Math.min(255,v+4));document.documentElement.style.setProperty('--accent-text','rgb('+accessible.join(',')+')');$('#theme-toggle').textContent=s.theme==='dark'?'Light mode':'Dark mode';$('#theme-toggle').setAttribute('aria-pressed',String(s.theme==='light'));$('#game-select').value=s.game;const profile=TrainerBoard.profile();$('.profile b').textContent=profile?.username||'Player';$('.avatar').textContent=(profile?.username||'P1').slice(0,2).toUpperCase();}
 function modal(html,locked=false){$('#modal-body').innerHTML=(!locked?'<button class="modal-close" data-action="close-modal" aria-label="Close">×</button>':'')+html;$('#modal').dataset.locked=String(locked);if(!$('#modal').open)$('#modal').showModal();}
 function closeModal(){if($('#modal').open)$('#modal').close();}
 function setup(){const p=TrainerBoard.profile(),s=state.settings;modal(`<form id="first-setup"><h2>${p?.setupComplete?'Your profile':'Set up your training'}</h2><label>Public username<input id="setup-name" autocomplete="nickname" minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" placeholder="3–20 letters, numbers or _" value="${esc(p?.username||'')}" required></label><div class="form-columns"><label>Controls<select id="setup-device">${['mouse','trackpad','touch'].map(v=>`<option value="${v}" ${s.device===v?'selected':''}>${v==='touch'?'Touchscreen':v==='mouse'?'Mouse':'Trackpad'}</option>`).join('')}</select></label><label>Theme<select id="setup-theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option></select></label></div><label class="check"><input id="setup-consent" type="checkbox" required><span>I confirm: my username and benchmark scores will be public.</span></label><p id="setup-error" class="form-error" role="alert"></p><button class="button primary full" type="submit">Confirm & continue</button></form>`,!p?.setupComplete);$('#first-setup').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;$('#setup-error').textContent='';try{await TrainerBoard.register($('#setup-name').value.trim(),$('#setup-consent').checked);const device=$('#setup-device').value;Object.assign(state.settings,{device,input:device==='touch'?'touch':'mouse',theme:$('#setup-theme').value});persist();closeModal();render();}catch(error){$('#setup-error').textContent=error.message;button.disabled=false;}});}
 const nav=[['training','Train'],['progress','Progress'],['leaderboard','Leaderboard'],['settings','Settings']];
 function render(){apply();$('#nav').innerHTML=nav.map(([id,name])=>`<a href="#${id}" class="nav-item ${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${icon(id)}<span>${name}</span></a>`).join('');$('#page-label').textContent=nav.find(x=>x[0]===page)[1];$('#main').innerHTML=({training,progress,leaderboard,settings})[page]();if(page==='leaderboard')loadBoard();}
 function navigate(id){if(active)return;page=nav.some(x=>x[0]===id)?id:'training';history.replaceState(null,'','#'+page);clearInterval(boardTimer);render();if(page==='leaderboard')boardTimer=setInterval(()=>{if(!document.hidden)loadBoard();},30000);}
 function preview(id){const s=skillBy(id);const shapes=id==='precision'?'<circle cx="86" cy="55" r="5"/><circle cx="156" cy="77" r="5"/><circle cx="210" cy="44" r="5"/><circle cx="105" cy="110" r="5"/><circle cx="235" cy="105" r="5"/><circle cx="178" cy="126" r="5"/>':id==='flick'?'<path d="M85 110 163 47 237 107" fill="none" stroke="currentColor" stroke-width="1" opacity=".35"/><circle cx="85" cy="110" r="12" opacity=".25"/><circle cx="163" cy="47" r="12"/><circle cx="237" cy="107" r="12" opacity=".25"/>':id==='tracking'?'<path d="M50 102C100 102 86 49 144 49S180 112 266 82" fill="none" stroke="currentColor" stroke-width="1.5" opacity=".35"/><circle cx="194" cy="91" r="13"/>':'<path d="M76 124h167m-167 0 9-6m-9 6 9 6m158-6-9-6m9 6-9 6" stroke="currentColor" stroke-width="1.5" fill="none" opacity=".5"/><circle cx="103" cy="65" r="8" opacity=".3"/><circle cx="217" cy="65" r="8"/>';
 return `<svg class="drill-preview" viewBox="0 0 320 160" aria-hidden="true" style="color:${s.color}"><path d="M28 25h264v118H28z" stroke="currentColor" stroke-width=".6" fill="none" opacity=".13"/><g fill="currentColor">${shapes}</g></svg>`;}
 function training(){const rec=C.recommendation(state).skill;return `<div class="page-heading"><h1>Training</h1>${btn('Train weakest','adaptive','secondary')}</div><div class="drill-grid">${C.skills.map(s=>{const v=C.summarize(state,s.id);return `<article class="drill-tile" style="--drill-color:${s.color}">${preview(s.id)}<div class="drill-copy"><div class="drill-title"><h2>${s.name}</h2><span>${v?'L'+v.level:'L3'}</span></div><p>${s.summary}</p><div class="drill-foot"><span>${v?v.value+'/100':'Not measured'}${s.id===rec.id&&C.overall(state).count?'<small>Recommended</small>':''}</span>${btn('Start','brief','primary',`data-skill="${s.id}"`)}</div></div></article>`;}).join('')}</div><div class="training-foot"><span>30-second drills · ${inputName()}</span>${btn('Benchmark all four','benchmark','quiet')}</div>`;}
 function progress(){const rows=C.records(state),summary=C.overall(state),selected=skillBy(chartSkill),sessions=C.records(state,chartSkill);return `<div class="page-heading"><h1>Progress</h1><span class="context-label">${state.settings.game==='cs2'?'CS2':'VALORANT'} · ${inputName()}</span></div>${!rows.length?`<div class="empty"><h2>Your starting point is next.</h2><p>Complete a drill to begin your history.</p>${btn('Choose a drill','training')}</div>`:`<div class="progress-summary"><div><b>${summary.value}</b><span>/100 skill score</span></div><span>${summary.count}/4 measured · ${Math.round(rows.reduce((n,r)=>n+r.duration,0)/60)} minutes</span></div><section class="panel"><div class="section-title"><h2>By drill</h2><span>First → current</span></div>${C.skills.map(s=>{const v=C.summarize(state,s.id);return `<div class="skill-row"><span class="skill-color" style="background:${s.color}"></span><b>${s.name}</b><span>${v?v.baseline+' → '+v.value:'—'}</span><span class="delta">${v?(v.delta>0?'+':'')+v.delta:'Unmeasured'}</span></div>`;}).join('')}</section><section class="panel"><div class="section-title"><h2>History</h2><label class="sr-only" for="chart-skill">Drill history</label><select id="chart-skill">${C.skills.map(s=>`<option value="${s.id}" ${chartSkill===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div>${sessions.length?chart(sessions,selected):'<p class="empty-inline">No results for this drill yet.</p>'}<div class="history-list">${rows.slice(-6).reverse().map(r=>`<div><span>${skillBy(r.skill)?.name}</span><small>${date(r.at)} · L${r.level}</small><b>${r.score}<small>/100</small></b></div>`).join('')}</div></section>`}<details class="archive-note"><summary>Earlier versions</summary><p>${state.sessions.length-rows.length} earlier or other-profile results are preserved in your backup. They don’t enter this four-drill score.</p></details>`;}
 function chart(rows,skill){const data=rows.slice(-20),points=data.map((r,i)=>[30+i*640/Math.max(1,data.length-1),175-r.score*1.4]),label=data.map(r=>r.score).join(', ');return `<svg class="history-chart" viewBox="0 0 700 205" role="img" aria-label="${skill.name} scores from oldest to newest: ${label}">${[0,50,100].map(n=>`<path d="M30 ${175-n*1.4}H670" stroke="var(--line)"/><text x="7" y="${179-n*1.4}">${n}</text>`).join('')}<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${skill.color}" stroke-width="2"/>${points.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.5" fill="${skill.color}"/>`).join('')}<text x="30" y="200">${date(data[0].at)}</text><text x="670" y="200" text-anchor="end">${date(data.at(-1).at)}</text></svg>`;}
 function leaderboard(){return `<div class="page-heading"><h1>Leaderboard</h1>${btn('Benchmark all four','benchmark')}</div><section class="panel"><div class="section-title"><h2>${state.settings.game==='cs2'?'CS2':'VALORANT'} <span>· ${inputName()}</span></h2>${btn('Refresh','refresh','quiet')}</div><div id="board-content" aria-live="polite"><p class="empty-inline">Loading scores…</p></div></section><details class="method-note"><summary>How the board works</summary><p>Complete all four 30-second, level 3 benchmarks. Each drill contributes equally to a composite out of 1000, using its latest three runs. Accuracy and pace count; tracking uses time on target while firing. Mouse, trackpad, touch and game profiles are separate. Results are browser-reported, not game ranks.</p></details>`;}
 let boardLoad=0;
 async function loadBoard(){const id=++boardLoad,el=$('#board-content'),game=state.settings.game,input=TrainerBoard.device(state.settings);if(!el)return;try{const data=await TrainerBoard.board(game,input);if(id!==boardLoad||!el.isConnected)return;el.innerHTML=data.players.length?`<div class="table-scroll"><table><thead><tr><th>Rank</th><th>Player</th><th>Score</th></tr></thead><tbody>${data.players.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.username)}</td><td><b>${p.score}</b><small>/1000</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline">No ranked players yet. Finish all four benchmarks to appear.</div>';}catch(error){if(el.isConnected)el.innerHTML=`<p class="form-error">${esc(error.message)}</p>${btn('Retry','refresh','secondary')}`;}}
 function crossPreview(){const s=state.settings,n=s.crossSize,g=s.crossGap,t=s.crossWidth;return `<svg viewBox="0 0 120 90" aria-label="Crosshair preview"><g stroke="${s.crosshair}" fill="${s.crosshair}" stroke-width="${t}">${s.crossStyle==='dot'?`<circle cx="60" cy="45" r="${t}" stroke="none"/>`:s.crossStyle==='circle'?`<circle cx="60" cy="45" r="${n}" fill="none"/>`:`<path d="M${60-n-g} 45h${n}m${2*g} 0h${n}M60 ${45-n-g}v${n}m0 ${2*g}v${n}"/>`}</g></svg>`;}
 function settings(){const s=state.settings;return `<div class="page-heading"><h1>Settings</h1>${btn('Public profile','profile','secondary')}</div><div class="settings-grid"><section class="panel"><h2>Controls</h2><label>Input<select data-setting="device">${['mouse','trackpad','touch'].map(v=>`<option value="${v}" ${v===s.device?'selected':''}>${v==='touch'?'Touchscreen':v==='mouse'?'Mouse':'Trackpad'}</option>`).join('')}</select></label><label>Firing<select data-setting="triggerMode"><option value="tap" ${s.triggerMode==='tap'?'selected':''}>Tap — one press, one shot</option><option value="auto" ${s.triggerMode==='auto'?'selected':''}>Hold — 10 shots/second</option></select></label><label>Look sensitivity <output id="sensitivity-value">${s.sensitivity}</output><input type="range" data-setting="sensitivity" min="0.2" max="3" step="0.05" value="${s.sensitivity}"></label><label>Field of view <output id="fov-value">${s.fov}°</output><input type="range" data-setting="fov" min="50" max="85" step="1" value="${s.fov}"></label><label class="check"><input type="checkbox" data-setting="sound" ${s.sound?'checked':''}>Hit sounds</label></section><section class="panel"><h2>Crosshair</h2><div id="cross-preview">${crossPreview()}</div><label>Shape<select data-setting="crossStyle">${['cross','dot','circle'].map(v=>`<option value="${v}" ${s.crossStyle===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Color<input type="color" data-setting="crosshair" value="${s.crosshair}"></label><label>Size<input type="range" data-setting="crossSize" min="2" max="20" value="${s.crossSize}"></label><label>Gap<input type="range" data-setting="crossGap" min="0" max="10" value="${s.crossGap}"></label><label>Width<input type="range" data-setting="crossWidth" min="1" max="4" step=".5" value="${s.crossWidth}"></label></section><section class="panel"><h2>Appearance</h2><label>Theme<select data-setting="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option></select></label><label>Accent<input type="color" data-setting="accent" value="${s.accent}"></label><label class="check"><input type="checkbox" data-setting="reduced" ${s.reduced?'checked':''}>Reduce motion & glow</label></section><section class="panel"><h2>Your data</h2><div class="data-actions">${btn('Export progress','export','secondary')}<label class="button secondary import-button">Import backup<input type="file" id="import-data" accept="application/json"></label>${btn('Remove public scores','withdraw','quiet')}</div><p class="setting-note">Backups include earlier versions. Your public device key stays in this browser.</p></section></div>`;}
 function brief(id,benchmark=false,queue=[]){const skill=skillBy(id);if(!skill)return;closeModal();active={skill,benchmark,queue,phase:'ready',level:benchmark?3:C.summarize(state,id)?.level||3,duration:30};const touch=C.inputMode(state.settings)==='touch';$('#range-root').innerHTML=`<section class="drill-brief" aria-labelledby="brief-title"><button class="quiet brief-back" data-action="exit">← Back</button><div class="brief-visual" style="--drill-color:${skill.color}">${preview(id)}</div><div class="brief-copy"><h1 id="brief-title">${skill.name}</h1><p>${skill.summary}</p><div class="brief-meta"><span>30 seconds</span><span>Level ${active.level}${benchmark?' · Benchmark':''}</span><span>${skill.focus}</span></div><div class="control-hint">${touch?'Drag to look · Tap or use Fire': 'Mouse to look · Click / F to fire'}${id==='stopfire'?(touch?' · Left stick to move':' · WASD to move'):''}${id==='tracking'?' · Hold to track':''}</div>${btn('Enter drill','launch','primary')}<details><summary>Scoring</summary><p>${id==='tracking'?'Your score is the share of the run spent aiming at the orb while holding fire.':'Accuracy and hits per second both count. '+(id==='stopfire'?'A hit counts after moving 0.65 m and settling on the ground.':'Every bright orb takes one hit.')}${benchmark?' The benchmark uses level 3 and a 64° field of view.':''}</p></details></div></section>`;document.body.classList.add('in-range');$('.app-shell').setAttribute('inert','');$('.app-shell').setAttribute('aria-hidden','true');$('#range-root [data-action=launch]').focus();}
 function fullscreen(){try{const p=document.documentElement.requestFullscreen?.();p?.catch?.(()=>{});}catch{}}
 function leaveFullscreen(){if(document.fullscreenElement){try{document.exitFullscreen()?.catch?.(()=>{});}catch{}}}
 async function launch(){if(!active||active.phase!=='ready')return;const a=active;if(a.benchmark&&state.settings.fov!==64){state.settings.fov=64;persist();}a.phase='loading';a.interrupted=false;a.prepared=false;const touch=C.inputMode(state.settings)==='touch';$('#range-root').innerHTML=`<section class="game-view" aria-label="${a.skill.name} drill" style="--drill-color:${a.skill.color}"><div class="game-toolbar"><b>${a.skill.name}</b><div class="game-metrics"><span><small>TIME</small><b id="metric-time">0:30</b></span><span><small>SCORE</small><b id="metric-score">0</b></span><span><small>${a.skill.id==='tracking'?'ON TARGET':'ACCURACY'}</small><b id="metric-accuracy">—</b></span></div><div>${btn('Pause','pause','quiet','id="pause-button" disabled')}${btn('Exit','exit','quiet')}</div></div><div class="game-arena"><canvas id="range-canvas" tabindex="0" aria-label="3D aim range"></canvas><canvas class="world-hud" aria-hidden="true"></canvas><span class="movement-cue" hidden></span><div id="game-overlay" class="game-overlay" role="status"><p>Preparing range…</p></div>${touch?`<div class="touch-controls">${a.skill.id==='stopfire'?'<button class="move-stick" aria-label="Movement joystick"><span class="stick-knob"></span></button>':''}<button class="fire-pad">FIRE</button></div>`:''}</div><div class="game-footer"><span>${touch?'Drag to look':'Esc to pause'}</span>${!touch?btn('Capture mouse','capture','quiet'):''}</div></section>`;fullscreen();try{range=new RangeTrainer($('#range-canvas'),state.settings,a.skill.id,a.level,a.duration,{update:updateHud,pause:paused,finish:finished,error:graphicsError});range.lock();await range.prepare();if(active!==a)return;if(a.benchmark){a.attempt=await TrainerBoard.begin(state.settings,{protocol:'benchmark',skill:a.skill,level:3});if(active!==a)return;if(a.attempt?.error)throw Error(a.attempt.error);}a.prepared=true;startCountdown(a);wireTouch();}catch(error){if(active!==a)return;range?.destroy();range=null;a.phase='error';graphicsError(error.message);}}
 function launchReady(a){return active===a&&!a.interrupted&&!document.hidden&&document.hasFocus();}
 function waitForLaunch(a){if(active!==a)return;clearTimeout(countdownTimer);a.interrupted=true;a.phase='waiting';$('#game-overlay').hidden=false;$('#game-overlay').innerHTML=`<h2>Ready when you are</h2>${btn('Start countdown','resume-countdown')}`;}
 function interruptLaunch(){const a=active;if(!a||!['loading','countdown','waiting'].includes(a.phase))return;a.interrupted=true;clearTimeout(countdownTimer);if(a.prepared)waitForLaunch(a);}
 function startCountdown(a){if(!launchReady(a)){waitForLaunch(a);return;}a.phase='countdown';let count=3;const show=()=>{if(active!==a)return;if(!launchReady(a)){waitForLaunch(a);return;}if(count>0){$('#game-overlay').innerHTML=`<b class="countdown">${count--}</b>`;countdownTimer=setTimeout(show,1000);}else{$('#game-overlay').hidden=true;$('#pause-button').disabled=false;a.phase='playing';range.start();}};show();}
 function updateHud(stats){if(!active||!$('#metric-time'))return;$('#metric-time').textContent='0:'+String(Math.ceil(Math.max(0,active.duration-stats.duration))).padStart(2,'0');$('#metric-score').textContent=String(C.score(stats.quality,active.level));$('#metric-accuracy').textContent=stats.trials?stats.accuracy+'%':'—';}
 function graphicsError(message){if(!active)return;active.phase='error';if($('#pause-button'))$('#pause-button').disabled=true;const overlay=$('#game-overlay');if(!overlay)return;overlay.hidden=false;const graphics=/WebGL|context|graphics|StratumFPS/.test(message);overlay.innerHTML=`<h2>${graphics?'3D graphics unavailable':'The drill couldn’t start'}</h2><p>${esc(graphics?'Enable browser hardware acceleration, then restart your browser.':message)}</p><div>${btn('Retry','retry','primary')}${!graphics&&active.benchmark?btn('Practice locally','local-practice','secondary'):''}${btn('Back to drills','exit','secondary')}</div>`;}
 function paused(){if(!active||active.phase==='error')return;active.phase='paused';$('#pause-button').disabled=true;$('#game-overlay').hidden=false;$('#game-overlay').innerHTML=`<h2>Paused</h2><div>${btn('Resume','resume')}${btn('Restart','retry','secondary')}</div>`;}
 function wireTouch(){const fire=$('.fire-pad');if(fire){fire.addEventListener('pointerdown',e=>{e.preventDefault();if(!range?.running||range.paused)return;fire.setPointerCapture(e.pointerId);range.pressFire(e,'pad:'+e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])fire.addEventListener(event,e=>range?.releasePointer(e));}const stick=$('.move-stick');if(!stick)return;let pointer=null;const move=e=>{if(e.pointerId!==pointer||!range)return;e.preventDefault();const b=stick.getBoundingClientRect(),x=(e.clientX-b.left-b.width/2)/(b.width*.35),y=(e.clientY-b.top-b.height/2)/(b.height*.35),length=Math.max(1,Math.hypot(x,y));range.touch={x:x/length,y:y/length};$('.stick-knob').style.transform=`translate(${x/length*23}px,${y/length*23}px)`;};stick.addEventListener('pointerdown',e=>{if(!range?.running||range.paused||pointer!==null)return;pointer=e.pointerId;stick.setPointerCapture(pointer);move(e);});stick.addEventListener('pointermove',move);const release=e=>{if(pointer!==e.pointerId)return;pointer=null;if(range)range.touch={x:0,y:0};$('.stick-knob').style.transform='';};for(const name of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(name,release);}
 function finished(result){const a=active;if(!a)return;a.phase='result';range?.destroy();range=null;const row={...result,skill:a.skill.id,context:C.context(state),at:Date.now(),protocol:a.benchmark?'benchmark':'practice',score:C.score(result.quality,a.level),level:a.level,nextLevel:C.nextLevel(a.level,result.quality)};state.sessions.push(row);persist();$('#range-root').innerHTML=`<section class="result-view"><span class="result-name">${a.skill.name}</span><h1>${row.score}<small>/100</small></h1><div class="result-stats"><span><b>${row.accuracy}%</b>${a.skill.id==='tracking'?'On target':'Accuracy'}</span><span><b>${a.skill.id==='tracking'?(row.success/10).toFixed(1)+'s':row.hits}</b>${a.skill.id==='tracking'?'Tracked':'Hits'}</span><span><b>L${row.nextLevel}</b>Next level</span></div><p id="result-save" aria-live="polite">Saved on this device</p><div class="result-actions">${btn(a.queue.length?'Next benchmark':'Train next skill','next')}${btn('Retry','retry','secondary')}${btn('Back to drills','exit','quiet')}</div></section>`;a.row=row;$('#range-root [data-action=next]').focus();if(a.benchmark&&a.attempt)TrainerBoard.submit(a.attempt,row).then(()=>{if(active===a)$('#result-save').textContent='Saved · public benchmark recorded';}).catch(error=>{if(active===a)$('#result-save').textContent='Saved locally · '+error.message;});}
 function exit(){clearTimeout(countdownTimer);range?.destroy();range=null;active=null;$('#range-root').replaceChildren();document.body.classList.remove('in-range');$('.app-shell').removeAttribute('inert');$('.app-shell').removeAttribute('aria-hidden');leaveFullscreen();render();$('#main').focus();}
 function retry(){const a=active;if(!a)return;clearTimeout(countdownTimer);range?.destroy();range=null;brief(a.skill.id,a.benchmark,a.queue);}
 function benchmark(){if(!TrainerBoard.profile()?.consent){setup();return;}brief(C.skills[0].id,true,C.skills.slice(1).map(s=>s.id));}
 function method(){modal(`<h2>About scoring</h2><p>Four physical drills: precision, switching, tracking and movement. Practice adapts between levels 1–8. Your local skill score combines accuracy, pace and difficulty. The public benchmark fixes level 3 and field of view, then weights all four drills equally.</p><p>Three.js renders the range; Rapier handles collision and hitscan. Firing is deterministic and recoil-free. CS2 and VALORANT profiles use separate movement settings and histories. These scores are not official game ranks.</p><p><a href="assets/engine-licenses.txt">Open-source licenses</a> · <a href="https://github.com/robertsoumx/MyTrainer">Source code</a></p>`);}
 async function withdraw(){modal(`<h2>Remove public scores?</h2><p>Your public username and scores will be removed. Local practice stays here.</p>${btn('Remove public profile','confirm-withdraw')}`);}
 const actions={'resume-countdown':()=>{if(!active?.prepared)return;active.interrupted=false;range?.lock();startCountdown(active);},'local-practice':()=>{if(!active)return;active.benchmark=false;active.queue=[];retry();},brief:el=>brief(el.dataset.skill),adaptive:()=>brief(C.recommendation(state).skill.id),training:()=>navigate('training'),profile:setup,theme:()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';persist();render();},'close-modal':closeModal,benchmark,refresh:loadBoard,launch,exit,retry,capture:()=>range?.lock(),pause:()=>range?.pause(),resume:()=>{if(!range)return;$('#game-overlay').hidden=true;$('#pause-button').disabled=false;active.phase='playing';range.resume();},next:()=>{const a=active;if(a.queue.length){const [next,...rest]=a.queue;brief(next,true,rest);}else if(a.benchmark){exit();navigate('leaderboard');}else brief(C.recommendation(state).skill.id);},method,withdraw,'confirm-withdraw':async()=>{const b=$('[data-action=confirm-withdraw]');b.disabled=true;try{await TrainerBoard.withdraw();closeModal();render();notify('Public profile removed.');}catch(error){b.disabled=false;notify(error.message,true);}},export:()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='stratum-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);const navLink=e.target.closest('.nav-item');if(navLink){e.preventDefault();navigate(navLink.hash.slice(1));}});
 document.addEventListener('input',e=>{const el=e.target,key=el.dataset.setting;if(!key)return;state.settings[key]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;if(key==='device')state.settings.input=el.value==='touch'?'touch':'mouse';persist();apply();if($('#cross-preview'))$('#cross-preview').innerHTML=crossPreview();if($('#sensitivity-value'))$('#sensitivity-value').value=state.settings.sensitivity;if($('#fov-value'))$('#fov-value').value=state.settings.fov+'°';});
 document.addEventListener('change',async e=>{if(e.target.id==='game-select'){state.settings.game=e.target.value;persist();render();}if(e.target.id==='chart-skill'){chartSkill=e.target.value;render();}if(e.target.id==='import-data'){try{const data=C.validate(JSON.parse(await e.target.files[0].text()));state=data;persist();render();notify('Progress imported.');}catch(error){notify(error.message||'Could not read this backup.',true);}}});
 $('#modal').addEventListener('cancel',e=>{if($('#modal').dataset.locked==='true')e.preventDefault();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active&&['ready','loading','countdown','waiting','error','result'].includes(active.phase))exit();});window.addEventListener('blur',interruptLaunch);document.addEventListener('visibilitychange',()=>{if(document.hidden)interruptLaunch();});window.addEventListener('hashchange',()=>{if(!active)navigate(location.hash.slice(1));});navigate(location.hash.slice(1));if(!TrainerBoard.profile()?.setupComplete)setup();
})();
